mapper.select:
		select distinct
			PROD_ID id,
			PROD_ABBR text
			/* 多级法人改造    需查询出fin_product.finprod_id字段   add by caojin  2020/6/9    start*/
			,fin_product.finprod_id finprodId
			/* 多级法人改造    需查询出fin_product.finprod_id字段   add by caojin  2020/6/9    end*/
		from
			REP_PROD_INFO
		/* 多级法人改造    需查询出fin_product.finprod_id字段   add by caojin  2020/6/9    start*/
		LEFT JOIN fin_product
		ON fin_product.FINPROD_MARKET_ID = REP_PROD_INFO.PROD_ID
		and fin_product.P_FINPROD_ID is null
		/* 多级法人改造    需查询出fin_product.finprod_id字段   add by caojin  2020/6/9    end*/
	    where STATUS='E'
	    /* and p_prod_id is null 不取子产品*/

	    	and (PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%'
            or PROD_ABBR like '%' || #{search, jdbcType=VARCHAR} || '%')


			 ${condition}

select distinct INDENTIFY_MARK id, HOLDER_NAME text from CHB_EQU_HOLD where STATUS='E'
and (INDENTIFY_MARK like '%' || #{search, jdbcType=VARCHAR} || '%' or HOLDER_NAME like '%' || #{search, jdbcType=VARCHAR} || '%')
${condition}

select distinct PROD_ID id, PROD_NAME text from REP_PROD_INFO where STATUS='E' and IS_GRADE = '02'
and (PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or PROD_NAME like '%' || #{search, jdbcType=VARCHAR} || '%')
and PROD_NAME = #{initValue}
union all select distinct rp1.PROD_ID id, concat(rp1.PROD_NAME,concat('(',concat(rp2.PROD_NAME,')'))) text from REP_PROD_INFO rp1 left join REP_PROD_INFO rp2 on rp1.P_PROD_ID = rp2.PROD_ID where rp1.STATUS='E' and rp2.IS_GRADE = '01'
and (rp1.PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or rp2.PROD_NAME like '%' || #{search, jdbcType=VARCHAR} || '%')
and rp2.PROD_NAME = #{initValue}

select distinct PROD_ID id, PROD_NAME text from REP_PROD_INFO where STATUS='E' and rep_prod_type in ('02','03') and ISSUE_STATUS ='01'
and (PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or PROD_ABBR like '%' || #{search, jdbcType=VARCHAR} || '%')
and p_prod_id = #{pprodid}
${condition}

select id ,text from ( select DPF.PROD_DISCOUNT_ID id, DPF.FEENAME text, RANK() OVER(PARTITION BY DPF.FEENAME order by DPF.PROD_DISCOUNT_ID) NUM from DIS_PROD_FEEDISCOUNT DPF left join REP_PROD_INFO RPI on DPF.prod_id=RPI.prod_id where DPF.DATA_STATUS='E' and (DPF.PROD_DISCOUNT_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or DPF.FEENAME like '%' || #{search, jdbcType=VARCHAR} || '%')
AND p_prod_id in
#{item,jdbcType=VARCHAR}
and RPI.raise_type = #{raiseType}
)where NUM=1

select id ,text, parentId from ( select DPA.PROD_ADJUST_ID id, DPA.ADJ_FIELD text, RPI.P_PROD_ID parentId, RANK() OVER(PARTITION BY DPA.ADJ_FIELD order by DPA.PROD_ADJUST_ID) NUM from DIS_PROD_ADJUST DPA left join REP_PROD_INFO RPI on DPA.prod_id=RPI.prod_id where DPA.DATA_STATUS='E' and (DPA.PROD_ID like '%' || #{search, jdbcType=VARCHAR} || '%' or DPA.ADJ_FIELD like '%' || #{search, jdbcType=VARCHAR} || '%')
and p_prod_id = #{pprodid}
and RPI.raise_type = #{raiseType}
)where NUM=1
